import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './History.css';

function History() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchOrders = async () => {
      const token = localStorage.getItem('token');
      const user = JSON.parse(localStorage.getItem('user'));
      
      if (!token || !user) {
        setLoading(false);
        return;
      }

      try {
        const response = await axios.get('/api/orders/user/me', {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        setOrders(response.data);
      } catch (error) {
        console.error('Error fetching orders:', error);
        // Fallback to userId if auth endpoint doesn't work
        try {
          const response = await axios.get(`/api/orders/user/${user.id}`);
          setOrders(response.data);
        } catch (err) {
          console.error('Error fetching orders by userId:', err);
        }
      } finally {
        setLoading(false);
      }
    };

    fetchOrders();
  }, []);

  const getStatusIcon = (status) => {
    if (status === 'completed' || status === 'Hoàn thành') return '✅';
    if (status === 'pending' || status === 'Đang xử lí') return '⏳';
    return '🔄';
  };

  const getStatusText = (status) => {
    const statusMap = {
      'pending': 'Đang xử lí',
      'completed': 'Hoàn thành',
      'paid': 'Đã thanh toán',
      'shipped': 'Đã gửi',
      'cancelled': 'Đã hủy',
      'Đang xử lí': 'Đang xử lí',
      'Hoàn thành': 'Hoàn thành'
    };
    return statusMap[status] || status;
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('vi-VN');
  };

  const getOrderName = (order) => {
    if (order.orderType === 'service') {
      return `${order.serviceName} - ${order.gameName}`;
    }
    // For product orders, show first item name or order ID
    if (order.items && order.items.length > 0) {
      return order.items[0].name || `Đơn hàng #${order._id.slice(-6)}`;
    }
    return `Đơn hàng #${order._id.slice(-6)}`;
  };

  if (loading) {
    return <div className="history-container"><div className="loading">Đang tải...</div></div>;
  }

  return (
    <div className="history-container">
      <h1>📋 LỊCH SỬ</h1>

      {orders.length === 0 ? (
        <div className="empty-state">
          <p>Bạn chưa có đơn hàng nào.</p>
          <button onClick={() => navigate('/products')} className="btn-primary">Mua ngay</button>
        </div>
      ) : (
        <div className="history-table">
          <div className="table-header">
            <div className="col-date">Ngày</div>
            <div className="col-account">Tên Đơn Hàng</div>
            <div className="col-amount">Giá</div>
            <div className="col-status">Trạng Thái</div>
            <div className="col-action">Hành Động</div>
          </div>

          {orders.map(order => (
            <div key={order._id} className={`table-row status-${getStatusText(order.status).replace(/\s+/g, '')}`}>
              <div className="col-date">{formatDate(order.createdAt)}</div>
              <div className="col-account">{getOrderName(order)}</div>
              <div className="col-amount">{order.totalAmount?.toLocaleString('vi-VN')} đ</div>
              <div className="col-status">
                <span className="status-badge">
                  {getStatusIcon(order.status)} {getStatusText(order.status)}
                </span>
              </div>
              <div className="col-action">
                <button className="btn-detail">Chi Tiết</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default History;
